import pandas as pd
import numpy as np

# Load the data
data = pd.read_csv('chunks_csv/outlierr/2021_no2.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Create a dictionary to store the neighbors for each borough
neighbors = {}
for index, row in adjacency.iterrows():
    if row['borough'] not in neighbors:
        neighbors[row['borough']] = []
    neighbors[row['borough']].append(row['neighbor'])

# Create a dictionary to store the NO2 values for each borough
no2_values = data.set_index('borough')['NO2_value'].to_dict()

# Create a dictionary to store the spatial weights matrix
spatial_weights_matrix = {}
for borough in neighbors:
    weights = []
    for neighbor in neighbors[borough]:
        weights.append(no2_values[neighbor])
    spatial_weights_matrix[borough] = np.array(weights)

# Compute the spatial lag of NO2 values
spatial_lag = {}
for borough in neighbors:
    neighbors_no2 = [no2_values[neighbor] for neighbor in neighbors[borough]]
    spatial_lag[borough] = np.mean(neighbors_no2)

# Compute the residuals
residuals = {}
for borough in neighbors:
    residuals[borough] = no2_values[borough] - spatial_lag[borough]

# Apply the ITERATIVE-R method
z_score = {}
for borough in neighbors:
    if len(neighbors[borough]) > 0:
        z_score[borough] = np.mean(residuals[borough]) / np.std(residuals[borough])
    else:
        z_score[borough] = np.nan

# Determine the outlier status
outlier_status = {}
for borough in neighbors:
    if np.isnan(z_score[borough]):
        outlier_status[borough] = 'NOT AN OUTLIER'
    elif z_score[borough] > 2:
        outlier_status[borough] = 'OUTLIER - HIGH'
    elif z_score[borough] < -2:
        outlier_status[borough] = 'OUTLIER - LOW'
    else:
        outlier_status[borough] = 'NOT AN OUTLIER'

# Print the results
print(f'data_points_used = {len(neighbors)}')
print(f'FINAL ANSWER: {outlier_status["Newham"]} (z = {z_score["Newham"]})')
print(f'z_score["Newham"] = {z_score["Newham"]}')
